import type { Config } from '../config.js';
export async function ollamaHealth(config: Config) { try { const response = await fetch(`${config.ollamaBaseUrl.replace(/\/$/, '')}/api/tags`, { signal: AbortSignal.timeout(5_000) }); if (!response.ok) return { reachable: false, modelAvailable: false }; const data = await response.json() as { models?: Array<{ name: string }> }; return { reachable: true, modelAvailable: Boolean(data.models?.some(model => model.name === config.ollamaModel)), models: data.models?.map(model => model.name) || [] }; } catch { return { reachable: false, modelAvailable: false, models: [] as string[] }; } }
export async function unloadModel(config: Config) { const response = await fetch(`${config.ollamaBaseUrl.replace(/\/$/, '')}/api/generate`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ model: config.ollamaModel, keep_alive: 0 }), signal: AbortSignal.timeout(15_000) }); if (!response.ok) throw new Error(`Ollama unload returned ${response.status}`); }
